-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다(두 통화 표의 줄 수·기존 권한·정책 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261104200000' and name='call_contact_choice')=1 then '예' else '아니오' end as value
union all select 'choice table present, empty, key and choice checks, one owner policy, RLS on',case when to_regclass('public.app_call_contact_choice') is not null and not exists(select 1 from public.app_call_contact_choice) and exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_call_contact_choice') and conname='app_call_contact_choice_key_check') and exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_call_contact_choice') and conname='app_call_contact_choice_choice_check') and (select count(*) from pg_policy where polrelid=to_regclass('public.app_call_contact_choice'))=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_call_contact_choice') and polroles=array['authenticated'::regrole]::oid[])=1 and exists(select 1 from pg_class where oid=to_regclass('public.app_call_contact_choice') and relrowsecurity and not relforcerowsecurity) then '예' else '아니오' end
union all select 'ref table present, empty, key and ref shape checks, one owner policy, RLS on',case when to_regclass('public.app_call_contact_ref') is not null and not exists(select 1 from public.app_call_contact_ref) and exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_call_contact_ref') and conname='app_call_contact_ref_key_check') and (select count(*) from pg_policy where polrelid=to_regclass('public.app_call_contact_ref'))=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_call_contact_ref') and polroles=array['authenticated'::regrole]::oid[])=1 and exists(select 1 from pg_class where oid=to_regclass('public.app_call_contact_ref') and relrowsecurity and not relforcerowsecurity) then '예' else '아니오' end
union all select 'app_call_move: definer, empty search_path, carries contact_key, only authenticated executes',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_call_move(uuid,text)') and p.prosecdef and p.proconfig=array['search_path=""'] and p.prosrc like '%app_call_contact_ref%' and p.prosrc like '%CALL_NOT_FOUND%' and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'authenticated: choice and ref read only, no write',case when has_table_privilege('authenticated','public.app_call_contact_choice','select') and has_table_privilege('authenticated','public.app_call_contact_ref','select') and not has_table_privilege('authenticated','public.app_call_contact_choice','insert') and not has_table_privilege('authenticated','public.app_call_contact_choice','update') and not has_table_privilege('authenticated','public.app_call_contact_choice','delete') and not has_table_privilege('authenticated','public.app_call_contact_ref','insert') and not has_table_privilege('authenticated','public.app_call_contact_ref','update') and not has_table_privilege('authenticated','public.app_call_contact_ref','delete') then '예' else '아니오' end
union all select 'service_role: choice three columns read only, ref insert only, no new write on the call tables',case when has_column_privilege('service_role','public.app_call_contact_choice','contact_key','select') and not has_column_privilege('service_role','public.app_call_contact_choice','updated_at','select') and not has_table_privilege('service_role','public.app_call_contact_choice','insert') and not has_any_column_privilege('service_role','public.app_call_contact_choice','update') and has_column_privilege('service_role','public.app_call_contact_ref','contact_key','insert') and not has_any_column_privilege('service_role','public.app_call_contact_ref','select') and not has_any_column_privilege('service_role','public.app_call_contact_ref','update') and not has_any_column_privilege('service_role','public.app_feed_items','update') and not has_any_column_privilege('service_role','public.app_call_personal','update') then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege on the four tables',case when not exists(select 1 from pg_class where oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_contact_choice'),to_regclass('public.app_call_contact_ref')) and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_contact_choice'),to_regclass('public.app_call_contact_ref')) and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'personal box rows',(select count(*)::text from public.app_call_personal)
union all select 'call tables grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'))),'')
  ||coalesce((select string_agg(c.relname||'.'||a.attname::text||':'||a.attacl::text,',' order by c.relname,a.attname) from pg_attribute a join pg_class c on c.oid=a.attrelid where a.attrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal')) and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'))),''));
